/**
 * ModelSetupBanner — sticky amber strip just under the topbar.
 *
 * Shows up when at least one of the three model slots
 * (`embedder`, `llm`, `skillEvolver`) is not usable. Hides itself
 * automatically as soon as the bridge reports all three as
 * `available=true` — the same flag `stores/health.ts` advertises as
 * "the viewer's setup banner uses this flag". The user can also
 * dismiss it manually with `✕`; that dismissal is persisted to
 * localStorage so a half-configured user doesn't get nagged forever.
 *
 * Display rules, in order:
 *   1. User clicked `✕` before          → hidden permanently.
 *   2. `health` hasn't loaded yet       → hidden (avoids flashing a red
 *                                          bar on first paint before we
 *                                          know whether anything's wrong).
 *   3. All three slots `available=true` → hidden (setup is complete).
 *   4. Otherwise                        → shown.
 *
 * Mounted as the second row of `.shell` (see `styles/layout.css`); the
 * row collapses to zero height when the banner is hidden.
 */
import { useState } from "preact/hooks";
import { t } from "../stores/i18n";
import { health } from "../stores/health";
import { navigate } from "../stores/router";
import { Icon } from "./Icon";

const STORAGE_KEY = "memos.banner.modelSetup.dismissed";

function isDismissed(): boolean {
  try {
    return window.localStorage.getItem(STORAGE_KEY) === "1";
  } catch {
    return false;
  }
}

function persistDismissed(): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, "1");
  } catch {
    /* localStorage may be unavailable (private mode) — degrade silently */
  }
}

export function ModelSetupBanner() {
  const [dismissed, setDismissed] = useState<boolean>(() => isDismissed());
  const h = health.value;

  if (dismissed || !h || modelsReady(h)) return null;

  const handleDismiss = () => {
    persistDismissed();
    setDismissed(true);
  };

  const handleGoSettings = (e: Event) => {
    e.preventDefault();
    navigate("/settings");
  };

  return (
    <div
      class="model-setup-banner"
      role="status"
      aria-label={t("banner.modelSetup.aria")}
    >
      <div class="model-setup-banner__icon" aria-hidden="true">
        <Icon name="circle-alert" size={16} />
      </div>
      <div class="model-setup-banner__body">
        <strong class="model-setup-banner__title">
          {t("banner.modelSetup.title")}
        </strong>
        <span class="model-setup-banner__msg">
          {t("banner.modelSetup.msg")}
        </span>
        <a
          class="model-setup-banner__cta"
          href="/settings"
          onClick={handleGoSettings}
        >
          {t("banner.modelSetup.cta")}
          <Icon name="arrow-up-right" size={12} />
        </a>
      </div>
      <button
        type="button"
        class="model-setup-banner__close"
        aria-label={t("banner.modelSetup.dismiss")}
        title={t("banner.modelSetup.dismiss")}
        onClick={handleDismiss}
      >
        <Icon name="x" size={16} />
      </button>
    </div>
  );
}

function modelsReady(h: NonNullable<typeof health.value>): boolean {
  return Boolean(
    h.llm?.available &&
      h.embedder?.available &&
      h.skillEvolver?.available,
  );
}

/**
 * Permission API Server
 *
 * HTTP server that the file-permission MCP server calls to request
 * user permission for file operations. This bridges the MCP server
 * (separate process) with the Electron UI.
 */

import http from 'http';
import type { BrowserWindow } from 'electron';
import type { PermissionRequest, FileOperation } from '@accomplish/shared';

export const PERMISSION_API_PORT = 9226;
export const QUESTION_API_PORT = 9227;

interface PendingPermission {
  resolve: (allowed: boolean) => void;
  timeoutId: NodeJS.Timeout;
}

interface PendingQuestion {
  resolveWithData: (data: { selectedOptions?: string[]; customText?: string; denied?: boolean }) => void;
  timeoutId: NodeJS.Timeout;
}

// Store pending permission requests waiting for user response
const pendingPermissions = new Map<string, PendingPermission>();

// Store pending question requests waiting for user response
const pendingQuestions = new Map<string, PendingQuestion>();

// Store reference to main window and task manager
let mainWindow: BrowserWindow | null = null;
let getActiveTaskId: (() => string | null) | null = null;

/**
 * Initialize the permission API with dependencies
 */
export function initPermissionApi(
  window: BrowserWindow,
  taskIdGetter: () => string | null
): void {
  mainWindow = window;
  getActiveTaskId = taskIdGetter;
}

/**
 * Resolve a pending permission request from the MCP server
 * Called when user responds via the UI
 */
export function resolvePermission(requestId: string, allowed: boolean): boolean {
  const pending = pendingPermissions.get(requestId);
  if (!pending) {
    return false;
  }

  clearTimeout(pending.timeoutId);
  pending.resolve(allowed);
  pendingPermissions.delete(requestId);
  return true;
}

/**
 * Resolve a pending question request from the MCP server
 * Called when user responds via the UI
 */
export function resolveQuestion(
  requestId: string,
  response: { selectedOptions?: string[]; customText?: string; denied?: boolean }
): boolean {
  const pending = pendingQuestions.get(requestId);
  if (!pending) {
    return false;
  }

  clearTimeout(pending.timeoutId);
  pending.resolveWithData(response);
  pendingQuestions.delete(requestId);
  return true;
}

/**
 * Generate a unique request ID for file permissions
 */
function generateRequestId(): string {
  return `filereq_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
}

/**
 * Generate a unique request ID for questions
 */
function generateQuestionRequestId(): string {
  return `questionreq_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
}

/**
 * Create and start the HTTP server for permission requests
 */
export function startPermissionApiServer(): http.Server {
  const server = http.createServer(async (req, res) => {
    // CORS headers for local requests
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    // Handle preflight
    if (req.method === 'OPTIONS') {
      res.writeHead(200);
      res.end();
      return;
    }

    // Only handle POST /permission
    if (req.method !== 'POST' || req.url !== '/permission') {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Not found' }));
      return;
    }

    // Parse request body
    let body = '';
    for await (const chunk of req) {
      body += chunk;
    }

    let data: {
      operation?: string;
      filePath?: string;
      filePaths?: string[];
      targetPath?: string;
      contentPreview?: string;
    };

    try {
      data = JSON.parse(body);
    } catch {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid JSON' }));
      return;
    }

    // Validate required fields
    if (!data.operation || (!data.filePath && (!data.filePaths || data.filePaths.length === 0))) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'operation and either filePath or filePaths are required' }));
      return;
    }

    // Validate operation type
    const validOperations = ['create', 'delete', 'rename', 'move', 'modify', 'overwrite'];
    if (!validOperations.includes(data.operation)) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: `Invalid operation. Must be one of: ${validOperations.join(', ')}` }));
      return;
    }

    // Check if we have the necessary dependencies
    if (!mainWindow || mainWindow.isDestroyed() || !getActiveTaskId) {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Permission API not initialized' }));
      return;
    }

    const taskId = getActiveTaskId();
    if (!taskId) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'No active task' }));
      return;
    }

    const requestId = generateRequestId();

    // Create permission request for the UI
    const permissionRequest: PermissionRequest = {
      id: requestId,
      taskId,
      type: 'file',
      fileOperation: data.operation as FileOperation,
      filePath: data.filePath,
      filePaths: data.filePaths,
      targetPath: data.targetPath,
      contentPreview: data.contentPreview?.substring(0, 500),
      createdAt: new Date().toISOString(),
    };

    // Send to renderer
    mainWindow.webContents.send('permission:request', permissionRequest);

    // Wait for user response (with 5 minute timeout)
    const PERMISSION_TIMEOUT_MS = 5 * 60 * 1000;

    try {
      const allowed = await new Promise<boolean>((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          pendingPermissions.delete(requestId);
          reject(new Error('Permission request timed out'));
        }, PERMISSION_TIMEOUT_MS);

        pendingPermissions.set(requestId, { resolve, timeoutId });
      });

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ allowed }));
    } catch (error) {
      res.writeHead(408, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Request timed out', allowed: false }));
    }
  });

  server.listen(PERMISSION_API_PORT, '127.0.0.1', () => {
    console.log(`[Permission API] Server listening on port ${PERMISSION_API_PORT}`);
  });

  server.on('error', (error: NodeJS.ErrnoException) => {
    if (error.code === 'EADDRINUSE') {
      console.warn(`[Permission API] Port ${PERMISSION_API_PORT} already in use, skipping server start`);
    } else {
      console.error('[Permission API] Server error:', error);
    }
  });

  return server;
}

/**
 * Create and start the HTTP server for question requests
 */
export function startQuestionApiServer(): http.Server {
  const server = http.createServer(async (req, res) => {
    // CORS headers for local requests
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    // Handle preflight
    if (req.method === 'OPTIONS') {
      res.writeHead(200);
      res.end();
      return;
    }

    // Only handle POST /question
    if (req.method !== 'POST' || req.url !== '/question') {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Not found' }));
      return;
    }

    // Parse request body
    let body = '';
    for await (const chunk of req) {
      body += chunk;
    }

    let data: {
      question?: string;
      header?: string;
      options?: Array<{ label: string; description?: string }>;
      multiSelect?: boolean;
    };

    try {
      data = JSON.parse(body);
    } catch {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid JSON' }));
      return;
    }

    // Validate required fields
    if (!data.question) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'question is required' }));
      return;
    }

    // Check if we have the necessary dependencies
    if (!mainWindow || mainWindow.isDestroyed() || !getActiveTaskId) {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Question API not initialized' }));
      return;
    }

    const taskId = getActiveTaskId();
    if (!taskId) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'No active task' }));
      return;
    }

    const requestId = generateQuestionRequestId();

    // Create question request for the UI
    const questionRequest: PermissionRequest = {
      id: requestId,
      taskId,
      type: 'question',
      question: data.question,
      header: data.header,
      options: data.options,
      multiSelect: data.multiSelect,
      createdAt: new Date().toISOString(),
    };

    // Send to renderer
    mainWindow.webContents.send('permission:request', questionRequest);

    // Wait for user response (with 5 minute timeout)
    const QUESTION_TIMEOUT_MS = 5 * 60 * 1000;

    try {
      const response = await new Promise<{ selectedOptions?: string[]; customText?: string; denied?: boolean }>((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          pendingQuestions.delete(requestId);
          reject(new Error('Question request timed out'));
        }, QUESTION_TIMEOUT_MS);

        pendingQuestions.set(requestId, { resolveWithData: resolve, timeoutId });
      });

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(response));
    } catch (error) {
      res.writeHead(408, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Request timed out', denied: true }));
    }
  });

  server.listen(QUESTION_API_PORT, '127.0.0.1', () => {
    console.log(`[Question API] Server listening on port ${QUESTION_API_PORT}`);
  });

  server.on('error', (error: NodeJS.ErrnoException) => {
    if (error.code === 'EADDRINUSE') {
      console.warn(`[Question API] Port ${QUESTION_API_PORT} already in use, skipping server start`);
    } else {
      console.error('[Question API] Server error:', error);
    }
  });

  return server;
}

/**
 * Check if a request ID is a file permission request from the MCP server
 */
export function isFilePermissionRequest(requestId: string): boolean {
  return requestId.startsWith('filereq_');
}

/**
 * Check if a request ID is a question request from the MCP server
 */
export function isQuestionRequest(requestId: string): boolean {
  return requestId.startsWith('questionreq_');
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { EventEmitter } from "node:events";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

vi.mock("node:child_process", async () => {
  const actual = await vi.importActual<typeof import("node:child_process")>("node:child_process");
  return {
    ...actual,
    exec: vi.fn(),
    execFile: vi.fn(),
    execSync: vi.fn(),
  };
});

import { exec, execFile } from "node:child_process";
import { SqliteStore } from "../src/storage/sqlite";
import { ViewerServer } from "../src/viewer/server";

const pluginPackageJson = fileURLToPath(new URL("../package.json", import.meta.url));
const noopLog = { debug: () => {}, info: () => {}, warn: () => {}, error: () => {} };

function createMockRequest(body: unknown) {
  const req = new EventEmitter() as any;
  req.pushBody = () => {
    req.emit("data", Buffer.from(JSON.stringify(body)));
    req.emit("end");
  };
  return req;
}

function invokeUpdateInstall(viewer: ViewerServer, body: unknown): Promise<{ statusCode: number; data: any }> {
  return new Promise((resolve) => {
    const req = createMockRequest(body);
    const res = {
      statusCode: 0,
      headers: {} as Record<string, string>,
      writeHead(code: number, headers: Record<string, string>) {
        this.statusCode = code;
        this.headers = headers;
      },
      end(payload: string) {
        resolve({ statusCode: this.statusCode, data: JSON.parse(payload) });
      },
    } as any;

    (viewer as any).handleUpdateInstall(req, res);
    req.pushBody();
  });
}

function seedExistingPlugin(extDir: string, version: string) {
  fs.mkdirSync(extDir, { recursive: true });
  fs.writeFileSync(
    path.join(extDir, "package.json"),
    JSON.stringify({ name: "@memtensor/memos-local-openclaw-plugin", version }, null, 2),
    "utf8",
  );
}

function installUpdateMocks(options: { newVersion: string; postinstallError?: Error; postinstallStderr?: string }) {
  const execMock = exec as any;
  const execFileMock = execFile as any;

  execMock.mockImplementation((command: string, execOptions: any, callback: Function) => {
    if (command.startsWith("npm pack ")) {
      callback(null, "memos-local-openclaw-plugin.tgz\n", "");
      return {} as any;
    }
    if (command.startsWith("tar -xzf ")) {
      const match = command.match(/ -C (.+)$/);
      if (!match) throw new Error(`Unexpected tar command: ${command}`);
      const extractDir = match[1];
      const pkgDir = path.join(extractDir, "package");
      fs.mkdirSync(path.join(pkgDir, "scripts"), { recursive: true });
      fs.writeFileSync(
        path.join(pkgDir, "package.json"),
        JSON.stringify({ name: "@memtensor/memos-local-openclaw-plugin", version: options.newVersion }, null, 2),
        "utf8",
      );
      fs.writeFileSync(path.join(pkgDir, "scripts", "postinstall.cjs"), "console.log('postinstall placeholder');\n", "utf8");
      callback(null, "", "");
      return {} as any;
    }
    throw new Error(`Unexpected exec command: ${command}`);
  });

  execFileMock.mockImplementation((file: string, args: string[], execOptions: any, callback: Function) => {
    if (args[0] === "install") {
      callback(null, "installed", "");
      return {} as any;
    }
    if (args[0] === "rebuild") {
      callback(null, "rebuilt", "");
      return {} as any;
    }
    if (file === process.execPath && args[0] === "scripts/postinstall.cjs") {
      if (options.postinstallError) {
        callback(options.postinstallError, "", options.postinstallStderr ?? "");
      } else {
        callback(null, "postinstall ok", "");
      }
      return {} as any;
    }
    throw new Error(`Unexpected execFile call: ${file} ${args.join(" ")}`);
  });
}

describe("viewer update-install", () => {
  let tmpDir = "";
  let homeDir = "";
  let store: SqliteStore | null = null;
  let viewer: ViewerServer | null = null;

  beforeEach(() => {
    vi.useFakeTimers();
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "memos-update-install-"));
    homeDir = path.join(tmpDir, "home");
    fs.mkdirSync(homeDir, { recursive: true });
    store = new SqliteStore(path.join(tmpDir, "viewer.db"), noopLog);
    viewer = new ViewerServer({
      store,
      embedder: { provider: "local" } as any,
      port: 19997,
      log: noopLog,
      dataDir: tmpDir,
    });

    vi.spyOn(os, "homedir").mockReturnValue(homeDir);
    vi.spyOn(viewer as any, "findPluginPackageJson").mockReturnValue(pluginPackageJson);
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
    store?.close();
    viewer = null;
    store = null;
    if (tmpDir) fs.rmSync(tmpDir, { recursive: true, force: true });
    tmpDir = "";
    homeDir = "";
  });

  it("rolls back and does not restart when postinstall fails", async () => {
    installUpdateMocks({
      newVersion: "2.0.0-beta.1",
      postinstallError: new Error("postinstall exploded"),
      postinstallStderr: "SyntaxError: duplicate declaration",
    });

    const extDir = path.join(homeDir, ".openclaw", "extensions", "memos-local-openclaw-plugin");
    seedExistingPlugin(extDir, "1.0.0");
    const killSpy = vi.spyOn(process, "kill").mockImplementation(() => true as any);

    const result = await invokeUpdateInstall(viewer!, { packageSpec: "@memtensor/memos-local-openclaw-plugin@beta" });

    expect(result.statusCode).toBe(200);
    expect(result.data.ok).toBe(false);
    expect(result.data.error).toContain("Postinstall failed");
    expect(result.data.error).toContain("duplicate declaration");
